# Descriptions françaises des tours de magie et sorts de niveau 1 (SRD 5.2) : (description, aux niveaux supérieurs).
_UP = "**Amélioration du tour de magie.** Les dégâts augmentent de {d} aux niveaux 5 ({a}), 11 ({b}) et 17 ({c})."
_BLOCK = "Le sort est bloqué par 30 cm de pierre, de terre ou de bois, 2,5 cm de métal ou une fine feuille de plomb."
_PLUS1 = "Vous pouvez cibler une créature de plus par niveau d'emplacement au-delà du 1."

SPELL_DESC = {
    "acid-splash": ("Vous créez une bulle d'acide qui explose en une sphère de 1,5 m de rayon à un point à portée. Chaque créature dans la sphère doit réussir un jet de sauvegarde de Dextérité ou subir 1d6 dégâts d'acide.\n" + _UP.format(d="1d6", a="2d6", b="3d6", c="4d6"), ""),
    "alarm": ("Vous posez une alarme contre les intrus sur une porte, une fenêtre ou une zone (cube de 6 m au plus). Jusqu'à la fin du sort, vous êtes alerté dès qu'une créature touche ou entre dans la zone (vous pouvez désigner des créatures qui ne la déclenchent pas).\n"
              "**Alarme sonore :** un bruit de clochette pendant 10 secondes, audible à 18 m.\n**Alarme mentale :** un signal mental si vous êtes à 1,5 km ou moins ; il vous réveille si vous dormez.", ""),
    "animal-friendship": ("Une bête que vous voyez à portée doit réussir un jet de sauvegarde de Sagesse ou être Charmée pour la durée du sort. Le sort prend fin si vous ou un allié lui infligez des dégâts.", "Une bête de plus par niveau d'emplacement au-delà du 1."),
    "bane": ("Jusqu'à trois créatures que vous voyez à portée font un jet de sauvegarde de Charisme. Celles qui échouent retirent 1d4 à leurs jets d'attaque et de sauvegarde jusqu'à la fin du sort.", _PLUS1),
    "bless": ("Vous bénissez jusqu'à trois créatures à portée. Jusqu'à la fin du sort, elles ajoutent 1d4 à leurs jets d'attaque et de sauvegarde.", _PLUS1),
    "burning-hands": ("Une nappe de flammes jaillit de vos mains. Chaque créature dans un cône de 4,5 m fait un jet de sauvegarde de Dextérité : 3d6 dégâts de feu en cas d'échec, la moitié en cas de réussite. Les objets inflammables non portés s'embrasent.", "+1d6 dégâts par niveau d'emplacement au-delà du 1."),
    "charm-person": ("Un humanoïde que vous voyez à portée fait un jet de sauvegarde de Sagesse (avec avantage si vous ou vos alliés le combattez). En cas d'échec, il est Charmé et vous considère comme un ami jusqu'à la fin du sort ou jusqu'à ce que vous ou vos alliés le blessiez. À la fin du sort, il sait que vous l'avez charmé.", _PLUS1),
    "chill-touch": ("Vous canalisez le froid de la tombe et faites une attaque de sort au corps à corps. Si elle touche, la cible subit 1d10 dégâts nécrotiques et ne peut pas récupérer de points de vie avant la fin de votre prochain tour.\n" + _UP.format(d="1d10", a="2d10", b="3d10", c="4d10"), ""),
    "chromatic-orb": ("Vous lancez un orbe d'énergie (acide, froid, feu, foudre, poison ou tonnerre, au choix) par une attaque de sort à distance : 3d8 dégâts du type choisi. Si deux dés de dégâts ou plus font le même résultat, l'orbe rebondit vers une autre cible à 9 m ou moins (nouvelle attaque, nouveaux dégâts).", "+1d8 dégâts par niveau au-delà du 1 ; l'orbe peut rebondir autant de fois que le niveau de l'emplacement, chaque créature une seule fois."),
    "color-spray": ("Un éventail de lumières colorées et éblouissantes jaillit de vous. Chaque créature dans un cône de 4,5 m doit réussir un jet de sauvegarde de Constitution ou être Aveuglée jusqu'à la fin de votre prochain tour.", ""),
    "command": ("Vous donnez un ordre d'un seul mot à une créature que vous voyez. Si elle rate un jet de sauvegarde de Sagesse, elle obéit à son prochain tour :\n**Approche :** elle vient vers vous par le plus court chemin.\n**Lâche :** elle lâche ce qu'elle tient.\n**Fuis :** elle s'éloigne de vous le plus vite possible.\n**À terre :** elle se jette À terre.\n**Halte :** elle ne bouge pas et n'agit pas.", _PLUS1),
    "comprehend-languages": ("Pendant la durée du sort, vous comprenez le sens littéral de toute langue parlée ou signée, et de tout texte que vous touchez (environ 1 minute par page). Le sort ne déchiffre ni les symboles ni les messages codés.", ""),
    "create-or-destroy-water": ("**Créer de l'eau :** jusqu'à 40 litres d'eau pure dans un récipient ouvert, ou une pluie dans un cube de 9 m qui éteint les flammes exposées.\n**Détruire de l'eau :** jusqu'à 40 litres d'eau dans un récipient ouvert, ou le brouillard dans un cube de 9 m.", "+40 litres, ou cube agrandi de 1,5 m, par niveau d'emplacement au-delà du 1."),
    "cure-wounds": ("Une créature que vous touchez récupère 2d8 + votre modificateur de caractéristique d'incantation en points de vie.", "+2d8 points de vie par niveau d'emplacement au-delà du 1."),
    "dancing-lights": ("Vous créez jusqu'à quatre lumières de la taille d'une torche (torches, lanternes ou orbes flottants), ou une seule forme lumineuse vaguement humaine. Chacune éclaire faiblement sur 3 m. Par une action bonus, vous les déplacez de 18 m ; elles doivent rester à 6 m les unes des autres.", ""),
    "detect-evil-and-good": ("Pendant la durée du sort, vous percevez l'emplacement des aberrations, célestes, élémentaires, fées, fiélons et morts-vivants à 9 m ou moins, ainsi que les lieux sanctifiés. " + _BLOCK, ""),
    "detect-magic": ("Pendant la durée du sort, vous percevez la présence de magie à 9 m ou moins. Par une action Magie, vous voyez une faible aura autour des créatures et objets magiques visibles, et l'école de magie d'un éventuel sort. " + _BLOCK, ""),
    "detect-poison-and-disease": ("Pendant la durée du sort, vous percevez l'emplacement et la nature des poisons, des créatures venimeuses et des maladies magiques à 9 m ou moins. " + _BLOCK, ""),
    "disguise-self": ("Vous changez d'apparence (vêtements, armure et équipement compris) jusqu'à la fin du sort : jusqu'à 30 cm de plus ou de moins, plus gros ou plus mince, avec la même silhouette générale. L'illusion ne résiste pas au toucher. Pour la percer, une créature doit vous examiner et réussir un test d'Intelligence (Investigation) contre le DD de vos sorts.", ""),
    "dissonant-whispers": ("Une créature que vous voyez entend une mélodie discordante dans sa tête. Jet de sauvegarde de Sagesse : en cas d'échec, 3d6 dégâts psychiques et elle doit utiliser sa réaction pour s'éloigner de vous au maximum ; en cas de réussite, la moitié des dégâts seulement.", "+1d6 dégâts par niveau d'emplacement au-delà du 1."),
    "divine-favor": ("Jusqu'à la fin du sort, vos attaques avec une arme infligent 1d4 dégâts radiants supplémentaires quand elles touchent.", ""),
    "divine-smite": ("Lancé quand vous touchez avec une arme ou à mains nues : la cible subit 2d8 dégâts radiants supplémentaires, +1d8 s'il s'agit d'un fiélon ou d'un mort-vivant.", "+1d8 dégâts par niveau d'emplacement au-delà du 1."),
    "druidcraft": ("Vous murmurez aux esprits de la nature et créez l'un de ces effets :\n**Météo :** un petit effet qui annonce le temps des 24 prochaines heures (orbe doré pour le beau temps, nuage pour la pluie…).\n**Floraison :** une fleur éclot, un bourgeon s'ouvre.\n**Effet sensoriel :** feuilles qui tombent, brise légère, cri d'animal, petites fées dansantes… dans un cube de 1,5 m.\n**Jeu de feu :** vous allumez ou éteignez une bougie, une torche ou un feu de camp.", ""),
    "eldritch-blast": ("Vous projetez un rayon d'énergie crépitante : attaque de sort à distance, 1d10 dégâts de force si elle touche.\n**Amélioration du tour de magie :** deux rayons au niveau 5, trois au niveau 11, quatre au niveau 17, sur une ou plusieurs cibles (une attaque par rayon).", ""),
    "elementalism": ("Vous commandez aux éléments et créez l'un de ces effets :\n**Air :** une brise qui agite les tissus et ferme les portes non retenues (cube de 1,5 m).\n**Terre :** une fine couche de poussière ou de sable, ou un mot écrit dans la terre.\n**Feu :** un petit nuage de braises inoffensives et de fumée colorée et parfumée, qui peut allumer bougies et torches.\n**Eau :** une brume fraîche, ou un verre d'eau pure qui s'évapore en 1 minute.\n**Sculpter :** donner pour 1 heure une forme grossière à un peu de terre, de feu, de fumée ou d'eau.", ""),
    "ensnaring-strike": ("Quand vous touchez une cible, des lianes l'enserrent : jet de sauvegarde de Force (avantage si elle est de taille G ou plus). En cas d'échec, elle est Entravée jusqu'à la fin du sort et subit 1d6 dégâts perforants au début de chacun de ses tours. Elle ou un allié peut tenter un test de Force (Athlétisme) contre le DD de vos sorts pour la libérer.", "+1d6 dégâts par niveau d'emplacement au-delà du 1."),
    "entangle": ("Des plantes agrippantes surgissent du sol sur un carré de 6 m : la zone devient un terrain difficile. Chaque autre créature présente doit réussir un jet de sauvegarde de Force ou être Entravée jusqu'à la fin du sort ; elle peut se libérer par un test de Force (Athlétisme) contre le DD de vos sorts.", ""),
    "expeditious-retreat": ("Vous effectuez l'action Foncer, et jusqu'à la fin du sort vous pouvez la refaire par une action bonus.", ""),
    "faerie-fire": ("Les objets d'un cube de 6 m sont soulignés d'une lumière bleue, verte ou violette, ainsi que les créatures qui ratent un jet de sauvegarde de Dextérité. Ils émettent une faible lumière sur 3 m et ne peuvent pas être Invisibles. Les attaques contre eux ont l'avantage si l'attaquant les voit.", ""),
    "false-life": ("Vous gagnez 2d4 + 4 points de vie temporaires.", "+5 points de vie temporaires par niveau d'emplacement au-delà du 1."),
    "feather-fall": ("Jusqu'à cinq créatures en chute à portée descendent lentement (18 m par round) jusqu'à la fin du sort. Elles ne subissent aucun dégât en atterrissant.", ""),
    "find-familiar": ("Vous obtenez un familier : un esprit qui prend la forme d'un petit animal de votre choix (chat, chouette, corbeau, crapaud, rat, araignée, faucon…). C'est un céleste, une fée ou un fiélon. Il agit seul mais vous obéit.\n**Lien télépathique :** à 30 m ou moins, vous lui parlez par la pensée ; par une action bonus, vous voyez et entendez à travers lui.\n**Toucher :** il peut délivrer vos sorts de contact.\n**Combat :** il a sa propre initiative mais ne peut pas attaquer.\n**Disparition :** à 0 PV, il disparaît jusqu'à ce que vous relanciez le sort. Un seul familier à la fois.", ""),
    "fire-bolt": ("Vous lancez une flammèche sur une créature ou un objet : attaque de sort à distance, 1d10 dégâts de feu si elle touche. Un objet inflammable non porté s'embrase.\n" + _UP.format(d="1d10", a="2d10", b="3d10", c="4d10"), ""),
    "floating-disk": ("Vous créez un disque de force horizontal de 90 cm de diamètre qui flotte à 90 cm du sol et porte jusqu'à 250 kg. Il vous suit en restant à 6 m de vous, peut monter des escaliers mais pas franchir un dénivelé de 3 m. Le sort prend fin si vous vous en éloignez de plus de 30 m.", ""),
    "fog-cloud": ("Vous créez une sphère de brouillard de 6 m de rayon, zone fortement obscurcie, jusqu'à la fin du sort ou jusqu'à ce qu'un vent fort la disperse.", "Le rayon augmente de 6 m par niveau d'emplacement au-delà du 1."),
    "goodberry": ("Dix baies magiques apparaissent dans votre main. Manger une baie (action bonus) rend 1 point de vie et nourrit une créature pour la journée. Les baies non mangées disparaissent à la fin du sort.", ""),
    "grease": ("Une graisse non inflammable couvre un carré de 3 m et en fait un terrain difficile. Chaque créature dans la zone, ou qui y entre ou y finit son tour, doit réussir un jet de sauvegarde de Dextérité ou tomber À terre.", ""),
    "guidance": ("Vous touchez une créature consentante et choisissez une compétence. Jusqu'à la fin du sort, elle ajoute 1d4 à ses tests avec cette compétence.", ""),
    "guiding-bolt": ("Un trait de lumière file vers une créature : attaque de sort à distance, 4d6 dégâts radiants si elle touche, et la prochaine attaque contre elle avant la fin de votre prochain tour a l'avantage.", "+1d6 dégâts par niveau d'emplacement au-delà du 1."),
    "healing-word": ("Une créature que vous voyez à portée récupère 2d4 + votre modificateur de caractéristique d'incantation en points de vie (sort lancé par une action bonus).", "+2d4 points de vie par niveau d'emplacement au-delà du 1."),
    "hellish-rebuke": ("En réaction, la créature qui vient de vous blesser est entourée de flammes vertes : jet de sauvegarde de Dextérité, 2d10 dégâts de feu en cas d'échec, la moitié en cas de réussite.", "+1d10 dégâts par niveau d'emplacement au-delà du 1."),
    "heroism": ("Une créature consentante que vous touchez est remplie de bravoure : jusqu'à la fin du sort, elle est immunisée contre l'état Effrayé et gagne, au début de chacun de ses tours, des points de vie temporaires égaux à votre modificateur de caractéristique d'incantation.", _PLUS1),
}

SPELL_DESC.update({
    "hex": ("Vous maudissez une créature que vous voyez. Jusqu'à la fin du sort, elle subit 1d6 dégâts nécrotiques supplémentaires chaque fois que vous la touchez, et a le désavantage aux tests d'une caractéristique de votre choix. Si elle tombe à 0 PV, vous pouvez transférer la malédiction à une autre créature par une action bonus.", "Durée plus longue : jusqu'à 4 heures (niveau 2), 8 heures (niveaux 3-4), 24 heures (niveau 5+)."),
    "hideous-laughter": ("Une créature que vous voyez fait un jet de sauvegarde de Sagesse. En cas d'échec, elle est prise d'un fou rire : À terre et Neutralisée pour la durée du sort, sans pouvoir se relever. Elle refait le jet à la fin de chacun de ses tours et quand elle subit des dégâts (avec avantage dans ce cas) ; une réussite met fin au sort.", _PLUS1),
    "hunters-mark": ("Vous marquez une créature que vous voyez comme votre proie. Jusqu'à la fin du sort, vous lui infligez 1d6 dégâts de force supplémentaires chaque fois que vous la touchez, et avez l'avantage aux tests de Sagesse (Perception ou Survie) pour la trouver. Si elle tombe à 0 PV, vous pouvez déplacer la marque par une action bonus.", "Durée plus longue : jusqu'à 8 heures (niveaux 3-4), 24 heures (niveau 5+)."),
    "ice-knife": ("Vous lancez un éclat de glace : attaque de sort à distance, 1d10 dégâts perforants si elle touche. Touché ou non, l'éclat explose : la cible et chaque créature à 1,5 m d'elle doivent réussir un jet de sauvegarde de Dextérité ou subir 2d6 dégâts de froid.", "+1d6 dégâts de froid par niveau d'emplacement au-delà du 1."),
    "identify": ("Vous touchez un objet pendant toute l'incantation : s'il est magique, vous apprenez ses propriétés, son mode d'emploi, s'il demande un lien, ses charges et les sorts qui l'affectent. Sur une créature, vous apprenez quels sorts l'affectent.", ""),
    "illusory-script": ("Vous écrivez un texte entouré d'une illusion : pour vous et les créatures désignées, il se lit normalement ; pour les autres, c'est une écriture magique incompréhensible, ou un tout autre message de votre choix. La vision véritable permet de lire le vrai message.", ""),
    "inflict-wounds": ("Une créature que vous touchez fait un jet de sauvegarde de Constitution : 2d10 dégâts nécrotiques en cas d'échec, la moitié en cas de réussite.", "+1d10 dégâts par niveau d'emplacement au-delà du 1."),
    "jump": ("Une créature consentante que vous touchez peut, une fois par tour jusqu'à la fin du sort, sauter jusqu'à 9 m en dépensant 3 m de mouvement.", _PLUS1),
    "light": ("Vous touchez un objet non porté par quelqu'un d'autre : il émet une lumière vive sur 6 m et faible sur 6 m de plus, de la couleur de votre choix, jusqu'à la fin du sort. Le couvrir bloque la lumière.", ""),
    "longstrider": ("La vitesse de la créature que vous touchez augmente de 3 m jusqu'à la fin du sort.", _PLUS1),
    "mage-armor": ("Une créature consentante sans armure que vous touchez a une CA de base de 13 + son modificateur de Dextérité jusqu'à la fin du sort (qui cesse si elle enfile une armure).", ""),
    "mage-hand": ("Une main spectrale apparaît à portée. Elle peut manipuler un objet, ouvrir une porte ou un contenant non verrouillé, ranger ou prendre un objet, verser une fiole. Par une action Magie, vous la redirigez et la déplacez de 9 m. Elle ne peut pas attaquer, activer un objet magique ni porter plus de 5 kg.", ""),
    "magic-missile": ("Trois fléchettes de force lumineuse frappent automatiquement les créatures que vous voyez à portée (une ou plusieurs) : 1d4 + 1 dégâts de force chacune.", "Une fléchette de plus par niveau d'emplacement au-delà du 1."),
    "mending": ("Vous réparez une seule cassure ou déchirure d'un objet que vous touchez (maillon brisé, clé cassée, cape déchirée, outre percée…), de 30 cm au plus, sans laisser de trace. Ne rend pas sa magie à un objet magique.", ""),
    "message": ("Vous désignez une créature à portée et lui murmurez un message qu'elle seule entend ; elle peut vous répondre en murmurant. Le sort passe à travers les obstacles si vous connaissez la cible, mais pas le silence magique, 30 cm de pierre, de métal ou de bois, ni une feuille de plomb.", ""),
    "minor-illusion": ("Vous créez un son ou l'image d'un objet (cube de 1,5 m au plus) pour la durée du sort.\n**Son :** d'un murmure à un cri, une voix, un rugissement, des tambours…\n**Image :** une chaise, des traces de pas, un petit coffre… purement visuelle, on passe au travers.\nUne créature qui examine l'illusion la perce avec un test d'Intelligence (Investigation) contre le DD de vos sorts.", ""),
    "poison-spray": ("Vous projetez une brume toxique : attaque de sort à distance, 1d12 dégâts de poison si elle touche.\n" + _UP.format(d="1d12", a="2d12", b="3d12", c="4d12"), ""),
    "prestidigitation": ("Petit tour de magie, au choix (jusqu'à trois effets durables à la fois) :\n**Effet sensoriel :** gerbe d'étincelles, souffle de vent, notes de musique, odeur étrange.\n**Jeu de feu :** allumer ou éteindre une bougie, une torche ou un petit feu.\n**Nettoyer ou salir** un petit objet.\n**Sensation :** refroidir, réchauffer ou parfumer un peu de matière pendant 1 heure.\n**Marque magique :** une couleur ou un symbole sur une surface pendant 1 heure.\n**Petite création :** un bibelot ou une image illusoire qui tient dans la main, jusqu'à la fin de votre prochain tour.", ""),
    "produce-flame": ("Une flamme sans chaleur apparaît dans votre main et éclaire vivement sur 6 m (faiblement sur 6 m de plus). Par une action Magie, vous pouvez la lancer sur une cible à 18 m : attaque de sort à distance, 1d8 dégâts de feu.\n" + _UP.format(d="1d8", a="2d8", b="3d8", c="4d8"), ""),
    "protection-from-evil-and-good": ("La créature consentante que vous touchez est protégée contre les aberrations, célestes, élémentaires, fées, fiélons et morts-vivants : ils ont le désavantage pour l'attaquer, et ne peuvent ni la posséder, ni la charmer, ni l'effrayer.", ""),
    "purify-food-and-drink": ("Vous retirez poison et pourriture de la nourriture et des boissons non magiques dans une sphère de 1,5 m de rayon.", ""),
    "ray-of-frost": ("Un rayon glacé file vers une créature : attaque de sort à distance, 1d8 dégâts de froid et vitesse réduite de 3 m jusqu'au début de votre prochain tour.\n" + _UP.format(d="1d8", a="2d8", b="3d8", c="4d8"), ""),
    "ray-of-sickness": ("Un rayon verdâtre file vers une créature : attaque de sort à distance, 2d8 dégâts de poison et elle est Empoisonnée jusqu'à la fin de votre prochain tour.", "+1d8 dégâts par niveau d'emplacement au-delà du 1."),
    "resistance": ("Vous touchez une créature consentante et choisissez un type de dégâts (acide, froid, feu, foudre, tonnerre, poison, nécrotique, radiant, contondant, perforant ou tranchant). Jusqu'à la fin du sort, quand elle subit ces dégâts, elle les réduit de 1d4 (une fois par tour).", ""),
    "sacred-flame": ("Une flamme radieuse descend sur une créature que vous voyez : elle doit réussir un jet de sauvegarde de Dextérité ou subir 1d8 dégâts radiants. Les abris partiels ne l'aident pas.\n" + _UP.format(d="1d8", a="2d8", b="3d8", c="4d8"), ""),
    "sanctuary": ("Vous protégez une créature : quiconque veut l'attaquer ou la viser d'un sort nuisible doit réussir un jet de sauvegarde de Sagesse, sinon il choisit une autre cible ou perd son attaque. Ne protège pas des zones d'effet. Le sort cesse si la créature protégée attaque, lance un sort ou inflige des dégâts.", ""),
    "searing-smite": ("Quand vous touchez une cible, elle subit 1d6 dégâts de feu supplémentaires et s'embrase : au début de chacun de ses tours, 1d6 dégâts de feu, puis un jet de sauvegarde de Constitution ; une réussite éteint les flammes.", "Tous les dégâts augmentent de 1d6 par niveau d'emplacement au-delà du 1."),
    "shield": ("En réaction quand vous êtes touché, une barrière de force invisible vous donne +5 à la CA jusqu'au début de votre prochain tour (y compris contre l'attaque qui l'a déclenchée), et Projectile magique ne vous fait rien.", ""),
    "shield-of-faith": ("Un champ scintillant entoure une créature de votre choix : +2 à la CA pour la durée du sort.", ""),
    "shillelagh": ("Le gourdin ou le bâton que vous tenez s'imprègne de la puissance de la nature : vous utilisez votre caractéristique d'incantation pour l'attaque et les dégâts, le dé de dégâts devient un d8, et les dégâts peuvent être de force.\n**Amélioration du tour de magie :** le dé passe à d10 (niveau 5), d12 (niveau 11), 2d6 (niveau 17).", ""),
    "shocking-grasp": ("Un éclair jaillit de votre main : attaque de sort au corps à corps, 1d8 dégâts de foudre, et la cible ne peut pas faire d'attaque d'opportunité avant son prochain tour.\n" + _UP.format(d="1d8", a="2d8", b="3d8", c="4d8"), ""),
    "silent-image": ("Vous créez l'image silencieuse d'un objet, d'une créature ou d'un phénomène (cube de 4,5 m au plus). Par une action Magie, vous la déplacez et l'animez. On passe au travers ; une créature qui l'examine la perce avec un test d'Intelligence (Investigation) contre le DD de vos sorts.", ""),
    "sleep": ("Les créatures de votre choix dans une sphère de 1,5 m de rayon doivent réussir un jet de sauvegarde de Sagesse ou être Neutralisées jusqu'à la fin de leur prochain tour ; si elles ratent un second jet, elles s'endorment (Inconscientes) pour la durée du sort. Des dégâts ou un allié qui les secoue les réveillent. Les elfes et les créatures qui ne dorment pas y sont insensibles.", ""),
    "sorcerous-burst": ("Vous lancez une salve d'énergie : attaque de sort à distance, 1d8 dégâts du type de votre choix (acide, froid, feu, foudre, poison, psychique ou tonnerre). Chaque 8 obtenu permet de lancer un d8 de plus (au maximum votre modificateur d'incantation).\n" + _UP.format(d="1d8", a="2d8", b="3d8", c="4d8"), ""),
    "spare-the-dying": ("Une créature à 0 point de vie, mais pas morte, devient stable.\n**Amélioration du tour de magie :** la portée double aux niveaux 5, 11 et 17.", ""),
    "speak-with-animals": ("Pendant la durée du sort, vous comprenez les bêtes et pouvez leur parler, et même les influencer. Elles parlent surtout de survie, mais peuvent vous renseigner sur les lieux et les monstres alentour, et sur ce qu'elles ont vu depuis la veille.", ""),
    "starry-wisp": ("Vous lancez une étincelle de lumière stellaire : attaque de sort à distance, 1d8 dégâts radiants, et la cible brille faiblement sur 3 m et ne peut pas être Invisible jusqu'à la fin de votre prochain tour.\n" + _UP.format(d="1d8", a="2d8", b="3d8", c="4d8"), ""),
    "thaumaturgy": ("Vous manifestez un petit prodige (jusqu'à trois effets d'une minute à la fois) :\n**Regard changé :** vos yeux changent d'aspect.\n**Voix tonnante :** votre voix porte trois fois plus fort, avec l'avantage aux tests d'Intimidation.\n**Jeu de flammes :** les flammes vacillent, grandissent ou changent de couleur.\n**Main invisible :** une porte ou une fenêtre non verrouillée s'ouvre ou claque.\n**Son fantôme :** grondement de tonnerre, cri de corbeau, murmures inquiétants…\n**Secousses :** le sol tremble sans danger.", ""),
    "thunderwave": ("Une vague de tonnerre jaillit de vous. Chaque créature dans un cube de 4,5 m fait un jet de sauvegarde de Constitution : en cas d'échec, 2d8 dégâts de tonnerre et elle est repoussée de 3 m ; en cas de réussite, la moitié des dégâts. Les objets non fixés sont repoussés, et le fracas s'entend à 90 m.", "+1d8 dégâts par niveau d'emplacement au-delà du 1."),
    "true-strike": ("Guidé par un éclair d'intuition magique, vous attaquez avec votre arme en utilisant votre caractéristique d'incantation au lieu de la Force ou de la Dextérité. Les dégâts peuvent être radiants.\n**Amélioration du tour de magie :** +1d6 dégâts radiants au niveau 5, 2d6 au niveau 11, 3d6 au niveau 17.", ""),
    "unseen-servant": ("Une force invisible et sans esprit (CA 10, 1 PV, ne peut pas attaquer) accomplit de petites tâches pour vous : aller chercher, nettoyer, plier, allumer un feu, servir à boire… Par une action bonus, vous lui donnez un ordre ; il se déplace de 4,5 m par tour. Le sort cesse s'il s'éloigne à plus de 18 m de vous.", ""),
    "vicious-mockery": ("Vous lancez une volée d'insultes enchantées à une créature qui vous voit ou vous entend : si elle rate un jet de sauvegarde de Sagesse, elle subit 1d6 dégâts psychiques et a le désavantage à sa prochaine attaque.\n" + _UP.format(d="1d6", a="2d6", b="3d6", c="4d6"), ""),
})
